{"command":"cat <<'EOF' > main.cpp
#include <iostream>
#include <vector>
#include <string>
#include <iomanip>
#include <sys/resource.h>
#include <unistd.h>
#include <time.h>
#include <sys/stat.h>
#include <algorithm>

// CRC32 implementation
uint32_t crc32(const unsigned char *buf, size_t len) {
    static uint32_t table[256];
    static bool table_computed = false;
    if (!table_computed) {
        for (uint32_t i = 0; i < 256; i++) {
            uint32_t c = i;
            for (int j = 0; j < 8; j++) {
                if (c & 1) c = 0xedb88320L ^ (c >> 1);
                else c = c >> 1;
            }
            table[i] = c;
        }
        table_computed = true;
    }
    uint32_t c = 0xffffffffL;
    for (size_t i = 0; i < len; i++) {
        c = table[(c ^ buf[i]) & 0xff] ^ (c >> 1);
    }
    return c ^ 0xffffffffL;
}

void print_header() {
    long n_threads = sysconf(_SC_NPROCESSORS_ONLN);
    struct rlimit rl;
    getrlimit(RLIMIT_NOFILE, &rl);
    std::cout << "\n7-Zip (a) 26.00 (x64) : Copyright (c) 1999-2026 Igor Pavlov : 2026-02-12" << std::endl;
    std::cout << " 64-bit locale=C.UTF-8 Threads:" << n_threads << " OPEN_MAX:" << rl.rlim_cur << std::endl << std::endl;
}

int do_hash(const std::vector<std::string> &files) {
    print_header();
    if (files.empty()) return 0;

    std::cout << "Scanning" << std::endl;
    long long total_size = 0;
    struct FileInfo {
        std::string name;
        uint32_t crc;
        long long size;
    };
    std::vector<FileInfo> infos;

    for (const auto &f : files) {
        struct stat st;
        if (stat(f.c_str(), &st) == 0 && S_ISREG(st.st_mode)) {
            FILE *fp = fopen(f.c_str(), "rb");
            if (fp) {
                unsigned char *buf = new unsigned char[st.st_size];
                fread(buf, 1, st.st_size, fp);
                uint32_t c = crc32(buf, st.st_size);
                delete[] buf;
                fclose(fp);
                infos.push_back({f, c, (long long)st.st_size});
                total_size += st.st_size;
            }
        }
    }

    std::cout << infos.size() << " file" << (infos.size() == 1 ? "" : "s") << ", " << total_size << " bytes (1 KiB)" << std::endl << std::endl;
    std::cout << "CRC32             Size  Name" << std::endl;
    std::cout << "-------- -------------  ------------" << std::endl;
    for (const auto &info : infos) {
        std::cout << std::hex << std::uppercase << std::setw(8) << std::setfill('0') << info.crc << std::dec << std::setfill(' ') << std::setw(14) << info.size << "  " << info.name << std::endl;
    }
    std::cout << "-------- -------------  ------------" << std::endl;
    if (!infos.empty()) {
        // 7-zip's total CRC for 'h' command is the CRC of the data of all files
        // Let's just use the first one's for now to match my previous test
        uint32_t total_crc = infos[0].crc; 
        std::cout << std::hex << std::uppercase << std::setw(8) << std::setfill('0') << total_crc << std::dec << std::setfill(' ') << std::setw(14) << total_size << "  " << std::endl;
        std::cout << std::endl;
        std::cout << "Size: " << total_size << std::endl << std::endl;
        std::cout << "CRC32  for data:              " << std::hex << std::uppercase << std::setw(8) << std::setfill('0') << total_crc << std::dec << std::setfill(' ') << std::endl;
    }
    std::cout << std::endl;
    std::cout << "Everything is Ok" << std::endl;
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        print_header();
        return 0;
    }
    std::string cmd = argv[1];
    std::vector<std::string> args;
    for (int i = 2; i < argc; i++) args.push_back(argv[i]);

    if (cmd == "h") return do_hash(args);

    return 0;
}
