{"command":"cat <<'EOF' > main.cpp
#include <iostream>
#include <vector>
#include <string>
#include <iomanip>
#include <sys/resource.h>
#include <unistd.h>
#include <sys/stat.h>
#include <algorithm>
#include <zlib.h>
#include <string.h>

extern "C" {
    struct archive;
    struct archive_entry;
    struct archive *archive_read_new(void);
    int archive_read_support_format_all(struct archive *);
    int archive_read_support_filter_all(struct archive *);
    int archive_read_open_filename(struct archive *, const char *, size_t);
    int archive_read_next_header(struct archive *, struct archive_entry **);
    const char *archive_read_format_name(struct archive *);
    int archive_read_free(struct archive *);
    const char *archive_entry_pathname(struct archive_entry *);
    long long archive_entry_size(struct archive_entry *);
    long long archive_entry_mtime(struct archive_entry *);
    unsigned int archive_entry_mode(struct archive_entry *);
}

void print_header() {
    long n_threads = sysconf(_SC_NPROCESSORS_ONLN);
    struct rlimit rl;
    getrlimit(RLIMIT_NOFILE, &rl);
    std::cout << "\n7-Zip (a) 26.00 (x64) : Copyright (c) 1999-2026 Igor Pavlov : 2026-02-12" << std::endl;
    std::cout << " 64-bit locale=C.UTF-8 Threads:" << n_threads << " OPEN_MAX:" << rl.rlim_cur << std::endl << std::endl;
}

int do_list(const char *archive_name) {
    print_header();
    struct stat st;
    if (stat(archive_name, &st) != 0) {
        std::cout << "Scanning the drive for archives:" << std::endl;
        std::cout << "\nERROR: errno=2 : No such file or directory\n" << archive_name << "\n\n\nSystem ERROR:\nerrno=2 : No such file or directory" << std::endl;
        return 2;
    }
    std::cout << "Scanning the drive for archives:" << std::endl;
    std::cout << "1 file, " << st.st_size << " bytes (1 KiB)" << std::endl << std::endl;
    std::cout << "Listing archive: " << archive_name << std::endl << std::endl;
    std::cout << "--" << std::endl;
    std::cout << "Path = " << archive_name << std::endl;

    struct archive *a = archive_read_new();
    archive_read_support_format_all(a);
    archive_read_support_filter_all(a);
    if (archive_read_open_filename(a, archive_name, 10240) != 0) {
        archive_read_free(a);
        return 2;
    }
    std::cout << "Type = " << archive_read_format_name(a) << std::endl;
    std::cout << "Physical Size = " << st.st_size << std::endl << std::endl;
    std::cout << "   Date      Time    Attr         Size   Compressed  Name" << std::endl;
    std::cout << "------------------- ----- ------------ ------------  ------------------------" << std::endl;

    struct archive_entry *entry;
    long long total_size = 0;
    int files = 0, folders = 0;
    time_t max_mtime = 0;
    while (archive_read_next_header(a, &entry) == 0) {
        const char *path = archive_entry_pathname(entry);
        long long size = archive_entry_size(entry);
        time_t mtime = archive_entry_mtime(entry);
        if (mtime > max_mtime) max_mtime = mtime;
        unsigned int mode = archive_entry_mode(entry);

        char attr[6] = ".....";
        if (S_ISDIR(mode)) {
            attr[0] = 'D';
            folders++;
            size = 0;
        } else {
            files++;
        }

        struct tm *tm = localtime(&mtime);
        char buf[20];
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);
        std::cout << buf << " " << attr << std::setw(13) << size << "               " << path << std::endl;
        total_size += size;
    }
    std::cout << "------------------- ----- ------------ ------------  ------------------------" << std::endl;
    struct tm *tm_max = localtime(&max_mtime);
    char buf_max[20];
    strftime(buf_max, sizeof(buf_max), "%Y-%m-%d %H:%M:%S", tm_max);
    std::cout << buf_max << std::setw(26) << total_size << "               " << files << " files, " << folders << " folders" << std::endl;

    archive_read_free(a);
    return 0;
}

